/* The packed object frame table and its decoder: a frame index resolves to the
 * table's (offset, rows, y bias, mode) entry, and a frame past the table
 * decodes as blank.
 *
 * The table's layout is one 4-byte word per slot:
 *
 *   off   = X & 0x3FFF  rows = X & 0x3F
 *   ybias = (X>>6) & 0x1F   mode = (X>>11) & 3
 *
 * The manifests tile APL\SPRITES.DAT (bankbase 0, 0x3080, 0xD3F0 x3, 0xE130).
 * Mode 1 -> 16 cols (1000:66EC), mode 2 -> 32 (1000:6C74), 0/3 -> nothing,
 * drawn at y + ybias.  The table lives in object_sprites.c, packed 4 bytes per
 * slot and generated by tools/sprite_frames.py; do not hand-edit it.
 * Deviation: D-265 (the port precomputes the boot-built table).
 */
#ifndef HUMANSRE_OBJECT_SPRITES_H
#define HUMANSRE_OBJECT_SPRITES_H

#include <stdint.h>

/* One decoded frame: the byte offset into the sprite bank and the row shape. */
typedef struct {
    uint32_t off;
    uint8_t rows, ybias, mode;
} ObjSprite;

/**
 * @brief The packed frame table's decoder.
 *
 * A frame past the table decodes as blank.
 *
 * @param frame the frame index
 * @return the decoded sprite
 */
ObjSprite object_sprite_at(uint32_t frame);

#endif /* HUMANSRE_OBJECT_SPRITES_H */
